package com.yeyamo_mobile.api.culture_service.infrastructure.outbox;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="culture_outbox") public class CultureOutbox{@Id private UUID id;@Column(name="aggregate_id",nullable=false)private String aggregateId;@Column(name="event_type",nullable=false)private String eventType;@Column(nullable=false,columnDefinition="TEXT")private String payload;@Column(name="occurred_at",nullable=false)private Instant occurredAt;@Column(name="published_at")private Instant publishedAt;@Column(nullable=false)private int attempts;@Column(name="last_error")private String lastError;protected CultureOutbox(){}public static CultureOutbox create(UUID id,String aggregate,String type,String payload,Instant occurred){CultureOutbox o=new CultureOutbox();o.id=id;o.aggregateId=aggregate;o.eventType=type;o.payload=payload;o.occurredAt=occurred;return o;}public UUID getId(){return id;}public String getEventType(){return eventType;}public String getPayload(){return payload;}public Instant getOccurredAt(){return occurredAt;}public Instant getPublishedAt(){return publishedAt;}public void published(){publishedAt=Instant.now();}public void failed(String error){attempts++;lastError=error==null?"unknown":error.substring(0,Math.min(1000,error.length()));}}
